// 请求体 schema 校验：类型 / 必填 / 边界 / 枚举 / 正则 / 嵌套数组 / 多余字段
function validate(schema, value, path) {
  path = path || '$';
  let errors = [];
  const t = schema.type;

  if (t === 'object') {
    if (typeof value !== 'object' || value === null || Array.isArray(value)) {
      return [path + ': expected object'];
    }
    for (const req of schema.required || []) {
      if (!Object.prototype.hasOwnProperty.call(value, req)) errors.push(path + '.' + req + ': required');
    }
    if (schema.additionalProperties === false) {
      for (const k of Object.keys(value)) {
        if (!Object.prototype.hasOwnProperty.call(schema.properties || {}, k))
          errors.push(path + '.' + k + ': additional property not allowed');
      }
    }
    for (const k of Object.keys(schema.properties || {})) {
      if (Object.prototype.hasOwnProperty.call(value, k))
        errors = errors.concat(validate(schema.properties[k], value[k], path + '.' + k));
    }
    return errors;
  }

  if (t === 'array') {
    if (!Array.isArray(value)) return [path + ': expected array'];
    if (schema.maxItems !== undefined && value.length > schema.maxItems)
      errors.push(path + ': maxItems is ' + schema.maxItems + ' (got ' + value.length + ')');
    value.forEach(function (v, i) { errors = errors.concat(validate(schema.items, v, path + '[' + i + ']')); });
    return errors;
  }

  if (t === 'string') {
    if (typeof value !== 'string') return [path + ': expected string'];
    if (schema.minLength !== undefined && value.length < schema.minLength)
      errors.push(path + ': minLength is ' + schema.minLength + ' (got ' + value.length + ')');
    if (schema.maxLength !== undefined && value.length > schema.maxLength)
      errors.push(path + ': maxLength is ' + schema.maxLength + ' (got ' + value.length + ')');
    if (schema.pattern !== undefined && !new RegExp(schema.pattern).test(value))
      errors.push(path + ': must match ' + schema.pattern);
    if (schema.enum !== undefined && schema.enum.indexOf(value) === -1)
      errors.push(path + ': must be one of ' + JSON.stringify(schema.enum));
    return errors;
  }

  if (t === 'integer') {
    if (!Number.isInteger(value)) return [path + ': expected integer'];
    if (schema.minimum !== undefined && value < schema.minimum) errors.push(path + ': minimum is ' + schema.minimum);
    if (schema.maximum !== undefined && value > schema.maximum) errors.push(path + ': maximum is ' + schema.maximum);
    return errors;
  }

  if (t === 'boolean') {
    if (typeof value !== 'boolean') errors.push(path + ': expected boolean');
    return errors;
  }

  errors.push(path + ': unknown schema type ' + t);
  return errors;
}

const ArticleCreate = {
  type: 'object',
  required: ['title', 'status'],
  additionalProperties: false,
  properties: {
    title: { type: 'string', minLength: 1, maxLength: 40 },
    status: { type: 'string', enum: ['draft', 'published'] },
    score: { type: 'integer', minimum: 0, maximum: 100 },
    slug: { type: 'string', pattern: '^[a-z0-9-]+$' },
    tags: { type: 'array', maxItems: 3, items: { type: 'string', maxLength: 12 } },
    featured: { type: 'boolean' },
  },
};

const good = [
  { title: 'sql index basics', status: 'published', score: 90, tags: ['sql', 'index'], featured: true },
  { title: 'REST design', status: 'draft' },
  { title: 'x', status: 'published', slug: 'rest-api-101', score: 0 },
  { title: 'n+1', status: 'published', tags: [] },
];
const bad = [
  { status: 'published' },
  { title: '', status: 'published' },
  { title: 'ok', status: 'archived' },
  { title: 'ok', status: 'published', score: 101 },
  { title: 'ok', status: 'published', score: 1.5 },
  { title: 'ok', status: 'published', tags: ['a', 'b', 'c', 'd'] },
  { title: 'ok', status: 'published', slug: 'Bad Slug' },
  { title: 'ok', status: 'published', featured: 'yes' },
  { title: 'ok', status: 'published', extraField: 1 },
  'not-an-object',
];

console.log('valid_cases:');
good.forEach(function (v, i) {
  const e = validate(ArticleCreate, v);
  console.log('  valid#' + i + ' ok=' + (e.length === 0) + ' errors=' + JSON.stringify(e));
});

console.log('invalid_cases:');
bad.forEach(function (v, i) {
  const e = validate(ArticleCreate, v);
  console.log('  invalid#' + i + ' ok=' + (e.length === 0) + ' errors=' + JSON.stringify(e));
});

const allGoodPass = good.every(function (v) { return validate(ArticleCreate, v).length === 0; });
const allBadFail = bad.every(function (v) { return validate(ArticleCreate, v).length > 0; });
console.log('all_valid_pass=' + allGoodPass);
console.log('all_invalid_rejected=' + allBadFail);
